import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.MapCreateLockedCopy{OriginalMapID: 300, NewMapID: -5}
COPY = bytes.fromhex("d80409")

# generated by gophertunnel b8bd735:
# &packet.MapCreateLockedCopy{OriginalMapID: -8589934592, NewMapID: 300}
WIDE_ID = bytes.fromhex("ffffffff3fd804")

# generated by gophertunnel b8bd735:
# &packet.MapCreateLockedCopy{}
ZERO = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(v2225.MapCreateLockedCopyPacket(original_map_id=300, new_map_id=-5), COPY, id="copy"),
    pytest.param(v2225.MapCreateLockedCopyPacket(original_map_id=-8589934592, new_map_id=300), WIDE_ID, id="64-bit-id"),
    pytest.param(v2225.MapCreateLockedCopyPacket(), ZERO, id="zero"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_map_create_locked_copy_is_packet_131(version):
    assert version.PACKETS[131] is version.MapCreateLockedCopyPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_map_create_locked_copy_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_map_create_locked_copy_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
